package com.nthexperience.desktop;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.ContactsContract;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
/** Searchable local address book and explicit read-only access to Android contacts. */
final class EightPeople extends LinearLayout {
    static final int READ=8603;final Activity activity;final DesktopStore store;final Consumer<String> open;final EditText search;final FrameLayout content;final TextView status;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());boolean device,favorites,closed;AlertDialog editor,detailDialog;int generation;
    EightPeople(Activity a,DesktopStore s,Consumer<String> open){super(a);activity=a;store=s;this.open=open;setOrientation(VERTICAL);setBackgroundColor(0xfffafafa);setContentDescription("Eight People");TenAppearance.preserve(this);EightAppUi.bar(a,this,"People",0xffd34c16);LinearLayout commands=EightAppUi.commands(a,this);commands.addView(EightAppUi.button(a,"Local contacts",()->{device=false;favorites=false;render();}));commands.addView(EightAppUi.button(a,"Device contacts",()->{device=true;favorites=false;if(permitted())render();else{render();activity.requestPermissions(new String[]{Manifest.permission.READ_CONTACTS},READ);}}));commands.addView(EightAppUi.button(a,"Favorites",()->{device=false;favorites=true;render();}));commands.addView(EightAppUi.button(a,"New contact",()->edit(null)));search=EightAppUi.input(a,this,"Search People",true);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int x,int n,int c){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int x,int b,int c){main.removeCallbacks(refresh);main.postDelayed(refresh,250);}});status=EightAppUi.text(a,"",13);status.setPadding(Aero.dp(a,14),Aero.dp(a,6),Aero.dp(a,14),Aero.dp(a,6));addView(status);content=new FrameLayout(a);addView(content,new LayoutParams(-1,0,1));render();}
    final Runnable refresh=this::render;
    boolean permitted(){return activity.checkSelfPermission(Manifest.permission.READ_CONTACTS)==PackageManager.PERMISSION_GRANTED;}
    void render(){if(closed)return;int request=++generation;String query=search==null?"":search.getText().toString().trim();if(device){if(!permitted()){status.setText("Device contacts are off. Local contacts remain available.");content.removeAllViews();LinearLayout c=Aero.column(activity);c.addView(EightAppUi.button(activity,"Allow contacts access",()->activity.requestPermissions(new String[]{Manifest.permission.READ_CONTACTS},READ)));content.addView(c);return;}status.setText("Loading device contacts…");worker.execute(()->{List<JSONObject> rows=new ArrayList<>();String error=null;try{Uri uri=query.isEmpty()?ContactsContract.Contacts.CONTENT_URI:Uri.withAppendedPath(ContactsContract.Contacts.CONTENT_FILTER_URI,Uri.encode(query));try(Cursor c=activity.getContentResolver().query(uri,new String[]{ContactsContract.Contacts._ID,ContactsContract.Contacts.DISPLAY_NAME_PRIMARY},null,null,ContactsContract.Contacts.SORT_KEY_PRIMARY+" ASC")){while(c!=null&&c.moveToNext()&&rows.size()<200){JSONObject p=new JSONObject();p.put("device",c.getLong(0)).put("name",c.isNull(1)?"Unnamed contact":c.getString(1));rows.add(p);}}}catch(Exception e){error="Contact access was removed or the provider is unavailable.";}String message=error;main.post(()->{if(!closed&&request==generation){status.setText(message==null?"Device contacts · up to 200 results. Refine your search for more.":message);show(rows);}});});return;}
        List<JSONObject> rows=new ArrayList<>();JSONArray all=EightPimStore.rows(store,EightPimModels.PEOPLE);String q=query.toLowerCase(Locale.ROOT);for(int i=0;i<all.length();i++){JSONObject p=all.optJSONObject(i);if(p!=null&&(!favorites||p.optBoolean("favorite"))&&(p.optString("name")+" "+p.optString("email")+" "+p.optString("phone")+" "+p.optString("address")).toLowerCase(Locale.ROOT).contains(q))rows.add(p);}rows.sort(Comparator.comparing(p->p.optString("name").toLowerCase(Locale.ROOT)));status.setText((favorites?"Favorites":"Local contacts")+" · "+rows.size());show(rows);
    }
    void show(List<JSONObject> rows){content.removeAllViews();if(rows.isEmpty()){TextView empty=EightAppUi.text(activity,"No contacts match. Add a local contact or choose Device contacts.",16);empty.setPadding(Aero.dp(activity,20),Aero.dp(activity,20),Aero.dp(activity,20),0);content.addView(empty);return;}List<String> labels=new ArrayList<>();for(JSONObject p:rows)labels.add((p.optBoolean("favorite")?"★ ":"")+p.optString("name")+(p.optString("email").isEmpty()?"":"\n"+p.optString("email")));ListView list=EightAppUi.list(activity,labels,n->{JSONObject p=rows.get(n);if(p.has("device"))loadDetails(p);else details(p);});list.setContentDescription("People contact list");content.addView(list,new FrameLayout.LayoutParams(-1,-1));}
    void loadDetails(JSONObject contact){long id=contact.optLong("device");int request=++generation;worker.execute(()->{JSONObject p;try{p=new JSONObject(contact.toString());p.put("phone",first(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,ContactsContract.CommonDataKinds.Phone.NUMBER,id));p.put("email",first(ContactsContract.CommonDataKinds.Email.CONTENT_URI,ContactsContract.CommonDataKinds.Email.ADDRESS,id));p.put("address",first(ContactsContract.CommonDataKinds.StructuredPostal.CONTENT_URI,ContactsContract.CommonDataKinds.StructuredPostal.FORMATTED_ADDRESS,id));JSONObject found=p;main.post(()->{if(!closed&&request==generation)details(found);});}catch(Exception e){main.post(()->{if(!closed&&request==generation){status.setText("Contact access is unavailable. Re-enable it in Device contacts.");render();}});}});}
    String first(Uri uri,String column,long id){try(Cursor c=activity.getContentResolver().query(uri,new String[]{column},ContactsContract.Data.CONTACT_ID+"=?",new String[]{String.valueOf(id)},null)){return c!=null&&c.moveToFirst()&&!c.isNull(0)?c.getString(0):"";}}
    void details(JSONObject p){LinearLayout body=EightAppUi.dialogBody(activity);EightAppUi.note(activity,body,p.optString("phone")+"\n"+p.optString("email")+"\n"+p.optString("address")+"\n"+p.optString("notes"));AlertDialog dialog=Aero.dialog(activity).setTitle(p.optString("name")).setView(EightAppUi.scroll(activity,body)).setNegativeButton("Close",null).create();if(!p.optString("phone").isEmpty()){body.addView(EightAppUi.button(activity,"Call",()->EightAppUi.launch(activity,new Intent(Intent.ACTION_DIAL,Uri.fromParts("tel",p.optString("phone"),null)))));body.addView(EightAppUi.button(activity,"Message",()->EightAppUi.launch(activity,new Intent(Intent.ACTION_SENDTO,Uri.fromParts("smsto",p.optString("phone"),null)))));}if(!p.optString("email").isEmpty())body.addView(EightAppUi.button(activity,"Write email",()->{dialog.dismiss();open.accept("eight-mailto:"+Uri.encode(p.optString("email")));}));if(!p.optString("address").isEmpty())body.addView(EightAppUi.button(activity,"Show address in Maps",()->{dialog.dismiss();open.accept("eight-map:"+Uri.encode(p.optString("address")));}));
        body.addView(EightAppUi.button(activity,p.has("device")?"Copy to local contacts":"Edit contact",()->{dialog.dismiss();if(p.has("device")){JSONObject local=EightPimModels.create();for(String key:new String[]{"name","phone","email","address"})GadgetLayout.put(local,key,p.optString(key));edit(local);}else edit(p);}));if(p.has("device"))body.addView(EightAppUi.button(activity,"Edit in device Contacts",()->EightAppUi.launch(activity,new Intent(Intent.ACTION_EDIT,ContentUris.withAppendedId(ContactsContract.Contacts.CONTENT_URI,p.optLong("device"))))));else body.addView(EightAppUi.button(activity,"Delete local contact",()->Aero.dialog(activity).setTitle("Delete "+p.optString("name")+"?").setMessage("Android contacts are unchanged.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,n)->{try{EightPimStore.delete(store,EightPimModels.PEOPLE,p.optString("id"));dialog.dismiss();render();}catch(JSONException e){EightAppUi.error(activity,e);}}).show()));detailDialog=dialog;dialog.show();}
    void edit(JSONObject previous){JSONObject p=previous==null?EightPimModels.create():previous;LinearLayout form=EightAppUi.dialogBody(activity);Map<String,EditText> fields=new LinkedHashMap<>();String[][] names={{"name","Contact name"},{"phone","Phone number"},{"email","Email address"},{"address","Postal address"},{"notes","Contact notes"}};for(String[] f:names){EditText value=EightAppUi.input(activity,form,f[1],!f[0].equals("notes")&&!f[0].equals("address"));value.setText(p.optString(f[0]));if(f[0].equals("phone"))value.setInputType(android.text.InputType.TYPE_CLASS_PHONE);if(f[0].equals("email"))value.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);fields.put(f[0],value);}CheckBox star=new CheckBox(activity);star.setText("Favorite contact");star.setTextColor(0xff222222);star.setChecked(p.optBoolean("favorite"));form.addView(star);AlertDialog dialog=Aero.dialog(activity).setTitle("Local contact").setView(EightAppUi.scroll(activity,form)).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{JSONObject row=new JSONObject(p.toString());for(Map.Entry<String,EditText> f:fields.entrySet())row.put(f.getKey(),f.getValue().getText().toString());row.put("favorite",star.isChecked());EightPimStore.save(store,EightPimModels.PEOPLE,row);device=false;render();dialog.dismiss();}catch(JSONException e){fields.get("name").setError(e.getMessage());}});editor=dialog;}
    JSONObject state(){JSONObject s=new JSONObject();GadgetLayout.put(s,"device",device);GadgetLayout.put(s,"favorites",favorites);GadgetLayout.put(s,"query",search.getText().toString());return s;}void restore(JSONObject s){if(s==null)return;device=s.optBoolean("device");favorites=s.optBoolean("favorites");search.setText(s.optString("query"));render();}
    void close(){if(editor!=null)editor.dismiss();if(detailDialog!=null)detailDialog.dismiss();closed=true;generation++;main.removeCallbacksAndMessages(null);worker.shutdownNow();}
}
